mapper.select:
SELECT id,row_version,template_version_id,actor_user_id,idempotency_key,request_hash,material_id,
  material_row_version,renderer_fingerprint,status,retry_count,error_code,error_message,create_by,create_time,update_time
FROM kb_render_job

   AND actor_user_id=#{actorUserId} 
   AND status=#{status} 
   AND idempotency_key=#{idempotencyKey} 

ORDER BY id DESC
